insert into public.tools (id, name, maker, url, cat, price, level, goals, prof, trusted, editor, blurb, steps, uses, africa, yt, ch, learn)
values
  ('chatgpt', 'ChatGPT', 'OpenAI', 'https://chatgpt.com', 'AI assistant', 'freemium', 1, array['writing','research','marketing','data','customers']::text[], array['all']::text[], true, 4.7, 'An all-round AI assistant for drafting, brainstorming, summarising and answering questions in plain language.', '["Create a free account at chatgpt.com or install the mobile app.", "Describe your business in 3–4 sentences and ask it for 10 ways it can save you time this week.", "Save your best prompts in a note so you can reuse them daily."]'::jsonb, '{"retail": "Write product descriptions, WhatsApp promos and price-list updates in minutes.", "hospitality": "Draft menus, reply to online reviews and plan weekly specials.", "agri": "Turn a buyer''s request into a clear quotation and plan planting calendars.", "services": "Summarise long documents and draft client emails (always review before sending).", "education": "Create lesson plans, quizzes and simplified explanations for learners.", "ngo": "Draft concept notes, donor reports and meeting summaries."}'::jsonb, null, 'ChatGPT tutorial for beginners', 'https://www.youtube.com/@OpenAI', '[{"label": "OpenAI Academy", "url": "https://academy.openai.com"}]'::jsonb),
  ('claude', 'Claude', 'Anthropic', 'https://claude.ai', 'AI assistant', 'freemium', 1, array['writing','research','data','finance']::text[], array['all']::text[], true, 4.7, 'A careful, long-document AI assistant — strong at reading reports, contracts and spreadsheets and writing clear drafts.', '["Sign up free at claude.ai (web or mobile app).", "Upload a real document — a report, price list or contract — and ask for a one-page summary with action points.", "Create a Project for your business so Claude remembers your context between chats."]'::jsonb, '{"services": "Review contracts and proposals, flag risky clauses and draft replies.", "ngo": "Condense 40-page donor guidelines into a checklist and first draft.", "office": "Turn messy notes and spreadsheets into clean reports.", "tech": "Explain, write and debug code; plan product specs."}'::jsonb, null, 'Claude AI tutorial for beginners', null, '[{"label": "Anthropic Academy", "url": "https://www.anthropic.com/learn"}]'::jsonb),
  ('gemini', 'Gemini', 'Google', 'https://gemini.google.com', 'AI assistant', 'freemium', 1, array['writing','research','data']::text[], array['all']::text[], true, 4.5, 'Google''s AI assistant, connected to Gmail, Docs, Drive and Maps — handy if your business already runs on Google.', '["Open gemini.google.com with your Google account.", "Ask it to summarise your last 10 unread emails or a Google Doc.", "Try the Android app for voice questions on the go."]'::jsonb, '{"retail": "Research suppliers and compare prices quickly.", "office": "Summarise email threads and draft replies inside Gmail.", "education": "Build study guides from your own notes."}'::jsonb, null, 'Google Gemini tutorial for beginners', null, '[{"label": "Grow with Google – AI Essentials", "url": "https://grow.google/ai-essentials/"}]'::jsonb),
  ('copilot', 'Microsoft Copilot', 'Microsoft', 'https://copilot.microsoft.com', 'AI assistant', 'free', 1, array['writing','research']::text[], array['office','services','education']::text[], false, 4.2, 'Microsoft''s free AI assistant with web search built in, available in the Edge browser, Windows and mobile.', '["Open copilot.microsoft.com or the Copilot app.", "Ask a research question and check the sources it links.", "Use it to draft a formal letter or email in your house style."]'::jsonb, '{"office": "Draft memos and quickly research unfamiliar topics."}'::jsonb, null, 'Microsoft Copilot tutorial for beginners', null, null),
  ('perplexity', 'Perplexity', 'Perplexity AI', 'https://www.perplexity.ai', 'Research', 'freemium', 1, array['research']::text[], array['all']::text[], true, 4.4, 'An AI search engine that answers with sources you can click and check — great for market research.', '["Go to perplexity.ai — no account needed to start.", "Ask: “Who are the main competitors for [your business] in [your city]?”", "Open the cited sources to verify before you act on anything."]'::jsonb, '{"agri": "Look up market prices, export requirements and new farming techniques.", "services": "Research regulations and industry news with citations.", "tech": "Scan the competitive landscape before you build."}'::jsonb, null, 'Perplexity AI tutorial for beginners', null, null),
  ('notebooklm', 'NotebookLM', 'Google', 'https://notebooklm.google.com', 'Research', 'free', 1, array['research','writing','meetings']::text[], array['education','ngo','services','office','health']::text[], true, 4.6, 'Upload your own documents and chat with them. It can even turn them into a podcast-style audio overview.', '["Open notebooklm.google.com with a Google account.", "Upload 2–5 PDFs, policies or reports you need to understand.", "Ask questions, then generate an Audio Overview to listen to on your commute."]'::jsonb, '{"education": "Turn a syllabus and readings into a study guide and quiz.", "ngo": "Compare several donor calls for proposals side by side.", "health": "Get to grips with long policy or guideline documents (not for patient data)."}'::jsonb, null, 'NotebookLM tutorial for beginners', null, null),
  ('grammarly', 'Grammarly', 'Grammarly', 'https://www.grammarly.com', 'Writing', 'freemium', 1, array['writing']::text[], array['office','services','sales','education']::text[], false, 4.2, 'Checks grammar and tone as you type in email, Word and the browser, and rewrites sentences on request.', '["Install the free browser extension or desktop app.", "Write your next client email and accept or reject its suggestions.", "Set your goals (formal, confident) so its tone advice fits you."]'::jsonb, '{}'::jsonb, null, 'Grammarly tutorial for beginners', null, null),
  ('canva', 'Canva', 'Canva', 'https://www.canva.com', 'Design', 'freemium', 1, array['design','marketing']::text[], array['all']::text[], true, 4.8, 'Design posters, social posts, flyers and presentations from templates, with AI tools to write, resize and edit images.', '["Sign up free and set up your Brand Kit (logo, colours, fonts).", "Pick a template for an Instagram or WhatsApp Status post and swap in your product.", "Use Magic Resize to turn one design into a poster, a post and a story."]'::jsonb, '{"retail": "Make weekly promo posters and price tags that look professional.", "hospitality": "Design menus, event flyers and room-rate cards.", "realestate": "Create property listing posts and brochures.", "ngo": "Registered nonprofits can apply for Canva for Nonprofits (free Pro features)."}'::jsonb, 'Registered NGOs can apply for free Canva Pro through Canva for Nonprofits.', 'Canva tutorial for beginners', 'https://www.youtube.com/@canva', '[{"label": "Canva Design School", "url": "https://www.canva.com/designschool/"}]'::jsonb),
  ('capcut', 'CapCut', 'ByteDance', 'https://www.capcut.com', 'Video', 'freemium', 1, array['design','marketing']::text[], array['retail','hospitality','creative','realestate','education']::text[], false, 4.4, 'Phone-friendly video editor with auto-captions, templates and AI effects for TikTok, Reels and WhatsApp Status.', '["Install CapCut on your phone.", "Film 3–5 short clips of your product or service.", "Use a template plus Auto Captions and post a 20-second video."]'::jsonb, '{"retail": "Show new stock arriving in a 15-second reel.", "realestate": "Turn a phone walkthrough into a captioned property tour."}'::jsonb, null, 'CapCut tutorial for beginners', null, null),
  ('adobe-express', 'Adobe Express', 'Adobe', 'https://www.adobe.com/express/', 'Design', 'freemium', 1, array['design','marketing']::text[], array['creative','retail','hospitality']::text[], false, 4.2, 'Quick graphics, short videos and flyers with Adobe''s Firefly AI for generating and editing images.', '["Sign up free with a Google or Adobe account.", "Try “Text to image” to generate a background for your next post.", "Schedule the post to your social pages from the same app."]'::jsonb, '{}'::jsonb, null, 'Adobe Express tutorial for beginners', null, null),
  ('meta-business-suite', 'Meta Business Suite', 'Meta', 'https://business.facebook.com', 'Social media', 'free', 1, array['marketing']::text[], array['retail','hospitality','creative','realestate','agri']::text[], true, 4.2, 'Plan and schedule Facebook and Instagram posts, manage messages in one inbox and get AI help writing ads.', '["Log in with the Facebook account that manages your business Page.", "Schedule a week of posts in one sitting using the Planner.", "Set up automated replies for common questions in the Inbox."]'::jsonb, '{"retail": "Batch-schedule a week of product posts every Monday."}'::jsonb, null, 'Meta Business Suite tutorial for beginners', null, null),
  ('whatsapp-business', 'WhatsApp Business', 'Meta', 'https://business.whatsapp.com', 'Customer chat', 'free', 1, array['customers','sales']::text[], array['retail','hospitality','agri','realestate','health','logistics','services']::text[], true, 4.6, 'Catalogue, quick replies, labels and away messages — plus Meta''s Business AI, which can answer customer chats for you.', '["Install WhatsApp Business and move your business number to it.", "Add your catalogue with prices and set a greeting and away message.", "Turn on the AI features in the app''s settings, starting with suggested replies you approve."]'::jsonb, '{"retail": "Answer “price?” and “do you deliver?” instantly, even at night.", "hospitality": "Take bookings and share the menu automatically.", "health": "Send appointment reminders and clinic hours (never share patient records).", "logistics": "Share delivery updates with labels for each order stage."}'::jsonb, 'Runs on low-cost Android phones; Meta has been rolling out its Business AI agent in the app.', 'WhatsApp Business tutorial for beginners', null, null),
  ('hubspot', 'HubSpot CRM', 'HubSpot', 'https://www.hubspot.com', 'Sales & CRM', 'freemium', 2, array['sales','customers','marketing']::text[], array['services','realestate','tech','sales','ngo']::text[], true, 4.4, 'A free CRM to track every lead and client, with AI to write emails, summarise records and score deals.', '["Create a free HubSpot account and import your contacts from a spreadsheet.", "Create a simple deal pipeline: New → Contacted → Proposal → Won.", "Use the AI email writer for your next follow-up."]'::jsonb, '{"realestate": "Track every buyer, viewing and offer in one pipeline.", "services": "Never lose a lead: log calls, set follow-up reminders."}'::jsonb, null, 'HubSpot CRM tutorial for beginners', 'https://www.youtube.com/@HubSpot', '[{"label": "HubSpot Academy (free courses)", "url": "https://academy.hubspot.com"}]'::jsonb),
  ('tidio', 'Tidio', 'Tidio', 'https://www.tidio.com', 'Customer chat', 'freemium', 2, array['customers']::text[], array['retail','hospitality','tech']::text[], false, 4.1, 'Website live chat with an AI agent (Lyro) that answers FAQs from your own content.', '["Sign up and add the chat widget to your website.", "Paste your FAQs so the AI can answer from them.", "Review conversations weekly and add missing answers."]'::jsonb, '{}'::jsonb, null, 'Tidio chatbot tutorial', null, null),
  ('manychat', 'ManyChat', 'ManyChat', 'https://manychat.com', 'Customer chat', 'freemium', 2, array['customers','marketing','automation']::text[], array['retail','creative','hospitality']::text[], false, 4.1, 'Automate Instagram, Facebook and WhatsApp DMs — reply to comments, capture leads and send offers.', '["Connect your Instagram or Facebook Page.", "Start with the “comment a keyword, get a DM” template.", "Track how many leads it captures in the first week."]'::jsonb, '{"creative": "Send a free guide automatically to anyone who comments a keyword."}'::jsonb, null, 'ManyChat tutorial for beginners', null, null),
  ('otter', 'Otter.ai', 'Otter.ai', 'https://otter.ai', 'Meetings', 'freemium', 1, array['meetings']::text[], array['office','services','ngo','education']::text[], false, 4.2, 'Records and transcribes meetings, then produces a summary and action items.', '["Sign up and connect your Google or Outlook calendar.", "Let it join your next Zoom, Meet or Teams call.", "Share the summary and action items with attendees."]'::jsonb, '{}'::jsonb, 'Tell participants you''re recording and follow your organisation''s data rules.', 'Otter.ai tutorial for beginners', null, null),
  ('fathom', 'Fathom', 'Fathom', 'https://fathom.video', 'Meetings', 'freemium', 1, array['meetings','sales']::text[], array['services','sales','tech','office']::text[], false, 4.3, 'A free AI notetaker for Zoom, Meet and Teams that writes summaries and next steps straight after the call.', '["Sign up and connect your calendar.", "Run your next client call as normal.", "Copy the auto-summary into your follow-up email."]'::jsonb, '{}'::jsonb, null, 'Fathom AI notetaker tutorial', null, null),
  ('notion', 'Notion', 'Notion Labs', 'https://www.notion.com', 'Productivity', 'freemium', 2, array['writing','meetings','data']::text[], array['tech','office','creative','ngo','education']::text[], false, 4.3, 'One workspace for notes, docs, projects and wikis, with built-in AI to write, summarise and find answers.', '["Sign up free and start from a template (e.g. project tracker).", "Move one real process in — like client onboarding steps.", "Ask Notion AI to summarise pages or draft new ones."]'::jsonb, '{}'::jsonb, null, 'Notion tutorial for beginners', 'https://www.youtube.com/@Notion', null),
  ('google-workspace', 'Google Workspace with Gemini', 'Google', 'https://workspace.google.com', 'Productivity', 'paid', 1, array['writing','meetings','data']::text[], array['office','services','ngo','education','tech']::text[], true, 4.3, 'Business Gmail, Docs, Sheets and Meet with Gemini built in to draft, summarise and analyse.', '["Start a free trial with your business domain.", "In Gmail, use “Help me write” for your next reply.", "In Sheets, ask Gemini to summarise or chart a table."]'::jsonb, '{}'::jsonb, null, 'Gemini in Google Workspace tutorial', 'https://www.youtube.com/@googleworkspace', null),
  ('m365-copilot', 'Microsoft 365 Copilot', 'Microsoft', 'https://www.microsoft.com/microsoft-365/copilot', 'Productivity', 'paid', 2, array['writing','data','meetings','finance']::text[], array['office','services','ngo']::text[], true, 4.2, 'Copilot inside Word, Excel, PowerPoint, Outlook and Teams — for teams already on Microsoft 365.', '["Check your Microsoft 365 plan includes Copilot, or add it.", "In Excel, ask Copilot to find trends in a sales sheet.", "In Teams, turn on meeting recap for your next call."]'::jsonb, '{"services": "Build Excel analyses and PowerPoint decks from a short brief."}'::jsonb, null, 'Microsoft 365 Copilot tutorial for beginners', 'https://www.youtube.com/@Microsoft365', null),
  ('zoho-books', 'Zoho Books', 'Zoho', 'https://www.zoho.com/books/', 'Finance', 'freemium', 2, array['finance']::text[], array['retail','services','ngo','hospitality','logistics','agri']::text[], true, 4.2, 'Cloud accounting with invoicing, expense tracking and payment reminders; the Zia assistant answers questions about your numbers.', '["Sign up and choose your country edition and currency.", "Create your first invoice and turn on automatic payment reminders.", "Snap receipts with the mobile app to log expenses."]'::jsonb, '{"retail": "Know daily profit, not just sales.", "ngo": "Track grant spending by project."}'::jsonb, null, 'Zoho Books tutorial for beginners', null, null),
  ('quickbooks', 'QuickBooks', 'Intuit', 'https://quickbooks.intuit.com', 'Finance', 'paid', 2, array['finance']::text[], array['services','retail']::text[], false, 4.0, 'Accounting software with AI help that categorises transactions and drafts invoices and reminders.', '["Start a trial and connect a bank feed or import statements.", "Let it auto-categorise a month of transactions and review them.", "Run a Profit & Loss report."]'::jsonb, '{}'::jsonb, null, 'QuickBooks Online tutorial for beginners', null, null),
  ('julius', 'Julius AI', 'Julius', 'https://julius.ai', 'Data', 'freemium', 1, array['data','finance']::text[], array['office','services','ngo','retail']::text[], false, 4.0, 'Upload a spreadsheet and ask questions in plain English; it builds charts and analysis for you.', '["Upload a sales or survey spreadsheet.", "Ask “What were my best and worst months, and why?”", "Export the chart for your report."]'::jsonb, '{}'::jsonb, null, 'Julius AI data analysis tutorial', null, null),
  ('zapier', 'Zapier', 'Zapier', 'https://zapier.com', 'Automation', 'freemium', 2, array['automation']::text[], array['tech','office','sales','services','creative']::text[], true, 4.4, 'Connect 7,000+ apps without code — e.g. new form entry → add to spreadsheet → send WhatsApp or email.', '["Sign up free and pick a ready-made template.", "Automate one repetitive task, e.g. save email attachments to Google Drive.", "Add an AI step to summarise or classify incoming messages."]'::jsonb, '{}'::jsonb, null, 'Zapier tutorial for beginners', 'https://www.youtube.com/@zapier', '[{"label": "Zapier Learn", "url": "https://zapier.com/learn"}]'::jsonb),
  ('make', 'Make', 'Make', 'https://www.make.com', 'Automation', 'freemium', 3, array['automation']::text[], array['tech','office','creative']::text[], false, 4.2, 'A visual automation builder for multi-step workflows; more flexible (and cheaper at volume) than simpler tools.', '["Sign up free and open a template scenario.", "Connect two apps you already use.", "Run it once manually, then schedule it."]'::jsonb, '{}'::jsonb, null, 'Make.com tutorial for beginners', null, null),
  ('n8n', 'n8n', 'n8n', 'https://n8n.io', 'Automation', 'freemium', 3, array['automation','data']::text[], array['tech']::text[], true, 4.4, 'Open-source workflow automation with AI agents. You can self-host it for free for full control of your data.', '["Try n8n Cloud or self-host with Docker.", "Import a community template (e.g. AI email triage).", "Add your own API keys and test step by step."]'::jsonb, '{"tech": "Build AI agents that read email, update your CRM and alert you on Slack or WhatsApp."}'::jsonb, null, 'n8n tutorial for beginners', 'https://www.youtube.com/@n8n-io', null),
  ('sunbird', 'Sunbird AI — Sunflower & Translate', 'Sunbird AI (Uganda)', 'https://sunflower.sunbird.ai', 'African languages', 'free', 1, array['language','customers','writing']::text[], array['all']::text[], true, 4.5, 'Ugandan-built AI assistant and translator for African languages. Use it to reach customers, farmers and communities in their own language.', '["Open sunflower.sunbird.ai (or translate.sunbird.ai for quick translation).", "Translate a short customer message or notice into Luganda, Runyankole, Acholi or another local language.", "Have a fluent speaker check important messages before sending."]'::jsonb, '{"agri": "Share planting and market-price updates with farmers in local languages.", "health": "Translate clinic notices and appointment instructions.", "ngo": "Translate community surveys and awareness messages.", "retail": "Advertise in the languages your customers actually speak."}'::jsonb, 'Built in Uganda. Sunflower supports 31 Ugandan languages among 67 African languages.', 'Sunbird AI Sunflower Uganda', null, '[{"label": "Sunbird Translate", "url": "https://translate.sunbird.ai"}]'::jsonb),
  ('google-translate', 'Google Translate', 'Google', 'https://translate.google.com', 'African languages', 'free', 1, array['language']::text[], array['all']::text[], true, 4.2, 'Text, voice and camera translation, including Swahili, Luganda and many other African languages.', '["Install the app and download offline language packs.", "Use the camera to translate a document or label.", "Use conversation mode with customers who speak another language."]'::jsonb, '{"hospitality": "Talk with guests from other countries using conversation mode."}'::jsonb, 'Offline language packs help where data is expensive or patchy.', 'Google Translate app tips tutorial', null, null),
  ('vulavula', 'Vulavula', 'Lelapa AI (South Africa)', 'https://lelapa.ai/products/vulavula/', 'African languages', 'freemium', 3, array['language','automation']::text[], array['tech']::text[], false, 3.9, 'Language AI for African languages (transcription, translation, entity recognition), available to developers through an API.', '["Sign up for developer access on the Lelapa AI site.", "Test transcription or translation on a sample in isiZulu or Sesotho.", "Build it into your app or customer-service flow."]'::jsonb, '{}'::jsonb, 'Built in Africa, focused on Southern African languages.', 'Lelapa AI Vulavula', null, null),
  ('plantvillage', 'PlantVillage Nuru', 'PlantVillage / Penn State', 'https://plantvillage.psu.edu', 'Agriculture', 'free', 1, array['research']::text[], array['agri']::text[], true, 4.3, 'Point your phone at a leaf and Nuru helps identify crop diseases such as cassava and maize problems. It works offline in the field.', '["Install the Nuru app from the Play Store.", "Scan a leaf in good daylight, holding the phone steady.", "Confirm the diagnosis with an extension officer before spraying."]'::jsonb, '{"agri": "Spot cassava and maize diseases early, even without internet."}'::jsonb, 'Designed with African farmers and works offline.', 'PlantVillage Nuru app', null, null),
  ('plantix', 'Plantix', 'Plantix', 'https://plantix.net', 'Agriculture', 'free', 1, array['research']::text[], array['agri']::text[], false, 4.1, 'A crop doctor app: photograph a sick plant and get a likely diagnosis and treatment tips.', '["Install Plantix on Android.", "Photograph the affected leaf or fruit.", "Read the treatment suggestions and check them with a local agronomist."]'::jsonb, '{}'::jsonb, null, 'Plantix app tutorial', null, null),
  ('heygen', 'HeyGen', 'HeyGen', 'https://www.heygen.com', 'Video', 'freemium', 2, array['design','language','marketing']::text[], array['creative','education','tech','sales']::text[], false, 4.1, 'Make presenter-style videos from a script, and translate your videos into other languages with lip-sync.', '["Sign up free and pick an avatar or record yourself.", "Paste a 60-second script about your product.", "Try video translation to reach a new-language audience."]'::jsonb, '{"education": "Turn a lesson script into a short explainer video."}'::jsonb, null, 'HeyGen tutorial for beginners', null, null),
  ('elevenlabs', 'ElevenLabs', 'ElevenLabs', 'https://elevenlabs.io', 'Voice', 'freemium', 1, array['design','language']::text[], array['creative','education']::text[], false, 4.3, 'Natural-sounding AI voiceovers and dubbing for ads, radio spots, training and audiobooks.', '["Sign up free and paste a short script.", "Choose a voice and adjust speed and style.", "Download the audio and add it to your video or radio ad."]'::jsonb, '{"creative": "Produce radio-style ads and voiceovers without a studio."}'::jsonb, null, 'ElevenLabs tutorial for beginners', null, null),
  ('descript', 'Descript', 'Descript', 'https://www.descript.com', 'Video', 'freemium', 2, array['design']::text[], array['creative','education']::text[], false, 4.1, 'Edit video and podcasts by editing the transcript, and remove filler words automatically.', '["Import a recording.", "Delete words in the transcript to cut the video.", "Use “Remove filler words” and export."]'::jsonb, '{}'::jsonb, null, 'Descript tutorial for beginners', null, null),
  ('gamma', 'Gamma', 'Gamma', 'https://gamma.app', 'Presentations', 'freemium', 1, array['design','writing']::text[], array['office','services','education','sales','ngo','tech']::text[], false, 4.3, 'Type an outline and get a polished presentation, document or one-page website in a minute.', '["Sign up free and click “Generate”.", "Paste your outline or notes.", "Edit the text and theme, then share a link or export to PowerPoint."]'::jsonb, '{"services": "Turn a proposal outline into a client-ready pitch deck."}'::jsonb, null, 'Gamma app tutorial for beginners', null, null),
  ('magicschool', 'MagicSchool', 'MagicSchool AI', 'https://www.magicschool.ai', 'Education', 'freemium', 1, array['writing']::text[], array['education']::text[], true, 4.5, 'AI tools built for teachers: lesson plans, rubrics, quizzes, report-card comments and differentiated reading.', '["Sign up free as an educator.", "Use the Lesson Plan generator for next week''s topic.", "Try “Text Leveler” to simplify a reading for struggling learners."]'::jsonb, '{"education": "Save hours on planning and marking every week."}'::jsonb, null, 'MagicSchool AI tutorial for teachers', null, null),
  ('heidi', 'Heidi Health', 'Heidi Health', 'https://www.heidihealth.com', 'Healthcare', 'freemium', 2, array['meetings','writing']::text[], array['health']::text[], false, 4.1, 'An AI medical scribe that drafts consultation notes and letters, so clinicians spend less time typing.', '["Sign up and choose your note templates.", "Use it for one consultation, with the patient''s consent.", "Review and edit every note before saving it to your records."]'::jsonb, '{"health": "Cut down after-hours documentation."}'::jsonb, 'Get patient consent and follow your country''s health-data rules before recording.', 'Heidi Health AI scribe tutorial', null, null),
  ('wix', 'Wix', 'Wix', 'https://www.wix.com', 'Websites', 'freemium', 1, array['web','marketing']::text[], array['retail','hospitality','services','realestate','creative','health']::text[], false, 4.2, 'Answer a few questions and Wix''s AI builds a website you can edit, with booking and online store options.', '["Sign up and choose “Create with AI”.", "Describe your business and pick a style.", "Add your WhatsApp number and Google Maps location, then publish."]'::jsonb, '{"hospitality": "Launch a site with menu, photos and bookings in an afternoon."}'::jsonb, null, 'Wix AI website builder tutorial', null, null),
  ('lovable', 'Lovable', 'Lovable', 'https://lovable.dev', 'Websites', 'freemium', 2, array['web','automation']::text[], array['tech','creative','services']::text[], true, 4.3, 'Describe the website or app you want in plain English and Lovable builds working software you can keep editing.', '["Sign up and describe your site: pages, sections, tone.", "Iterate by chatting: “make the hero bolder”, “add a contact form”.", "Connect a custom domain and publish."]'::jsonb, '{"tech": "Prototype an MVP in days, not months."}'::jsonb, null, 'Lovable AI app builder tutorial', null, null),
  ('github-copilot', 'GitHub Copilot', 'GitHub', 'https://github.com/features/copilot', 'Developer', 'freemium', 3, array['web','automation']::text[], array['tech']::text[], true, 4.5, 'An AI pair-programmer in VS Code and other editors that suggests code, explains it and helps fix bugs.', '["Enable Copilot Free in your GitHub account.", "Install the extension in VS Code.", "Ask Copilot Chat to explain a file, then to write tests for it."]'::jsonb, '{}'::jsonb, null, 'GitHub Copilot tutorial for beginners', null, null),
  ('cursor', 'Cursor', 'Anysphere', 'https://cursor.com', 'Developer', 'freemium', 3, array['web','automation']::text[], array['tech']::text[], false, 4.4, 'An AI-first code editor that can change code across a whole project from one instruction.', '["Download Cursor and open an existing project.", "Ask it to explain the codebase.", "Make a small feature change with the agent and review the diff."]'::jsonb, '{}'::jsonb, null, 'Cursor AI editor tutorial for beginners', null, null),
