-- Zentia Tool Hub: the 46 vetted tools. Generated from src/data/tool-catalog.json.
-- Safe to run more than once: existing tools are updated, ratings are kept.
on conflict (id) do update set name = excluded.name, maker = excluded.maker, url = excluded.url, cat = excluded.cat, price = excluded.price, level = excluded.level, goals = excluded.goals, prof = excluded.prof, trusted = excluded.trusted, editor = excluded.editor, blurb = excluded.blurb, steps = excluded.steps, uses = excluded.uses, africa = excluded.africa, yt = excluded.yt, ch = excluded.ch, learn = excluded.learn;

select private.refresh_daily_picks();
